public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int count = 0;
    boolean[][] visited = new boolean[grid.length][];
    for (int i=0;i<grid.length;i++){
        if (grid[i]==null) continue;
        visited[i] = new boolean[grid[i].length];
    }
    for (int i=0;i<grid.length;i++){
        if (grid[i]==null) continue;
        for (int j=0;j<grid[i].length;j++){
            if (grid[i][j]=='@' && !visited[i][j]){
                count++;
                dfs(i,j,grid,visited);
            }
        }
    }
    return count;
}

private static void dfs(int i,int j,char[][] grid,boolean[][] visited){
    int rows = grid.length;
    int[] dRow = {-1,-1,-1,0,0,1,1,1};
    int[] dCol = {-1,0,1,-1,1,-1,0,1};
    visited[i][j]=true;
    for (int k=0;k<8;k++){
        int ni = i + dRow[k];
        int nj = j + dCol[k];
        if (ni>=0 && ni<rows && grid[ni]!=null && nj>=0 && nj<grid[ni].length && grid[ni][nj]=='@' && !visited[ni][nj]){
            dfs(ni,nj,grid,visited);
        }
    }
}

