public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i=0;i<n;i++) graph[i] = new ArrayList<>();
    for (int[] e: edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] timeHolder = new int[1];
    dfs(0,-1,graph,hasApple,timeHolder);
    return timeHolder[0];
}

private boolean dfs(int node,int parent,List<Integer>[] graph,boolean[] hasApple,int[] timeHolder) {
    boolean hasAppleInSubtree = hasApple[node];
    for (int neighbor: graph[node]) {
        if (neighbor==parent) continue;
        boolean childHasApple = dfs(neighbor,node,graph,hasApple,timeHolder);
        if (childHasApple) {
            timeHolder[0] += 2;
            hasAppleInSubtree = true;
        }
    }
    return hasAppleInSubtree;
}

