/**
 * Adds a dot ('.') as a thousand separator every three digits of the given integer and returns the result as a string.
 *
 * @param n The integer to add thousand separators to.
 * @return The string with thousand separators added.
 */
public static String addThousandSeparator(int n) {
    // Handle zero directly
    if (n == 0) {
        return "0";
    }

    // Determine sign and work with absolute value using long to avoid overflow of Integer.MIN_VALUE
    boolean negative = n < 0;
    long absValue = Math.abs((long) n);
    String numberStr = Long.toString(absValue);

    // Build the formatted string with separators
    StringBuilder formatted = new StringBuilder();
    int count = 0;
    for (int i = numberStr.length() - 1; i >= 0; i--) {
        formatted.append(numberStr.charAt(i));
        count++;
        if (count % 3 == 0 && i != 0) {
            formatted.append('.');
        }
    }

    // Reverse to correct order
    formatted.reverse();

    // Add negative sign if needed
    if (negative) {
        formatted.insert(0, '-');
    }

    return formatted.toString();
}

